    rig = r.json()
    for k in ["name", "status", "ip", "kernel", "osSeries", "osVersion",
              "executeStatus", "ocCore", "ocMemory", "ocPowerLimit", "ocVddc"]:
        print(f"  {k}: {rig.get(k, '')}")
